const meta = $node["Parse & Prepare Data"].json;
const ai = $node["OpenAI: Generate Body"].json;

const slug = meta.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const isoDate = new Date().toISOString().split('T')[0]; // YYYY-MM-DD format
const order = meta.db.next_orders.crypto_ogs;

// Title Case the person's name (form input arrives lowercase, e.g. "kris marszalek")
function toTitleCase(s) {
  return String(s).trim().toLowerCase().split(/\s+/).map(word =>
    word.split('-').map(part =>
      part.replace(/^(o'|mc|mac)?(.)/, (mm, pre, ch) =>
        (pre ? pre.charAt(0).toUpperCase() + pre.slice(1) : '') + ch.toUpperCase())
    ).join('-')
  ).join(' ');
}
const title = toTitleCase(meta.name);

// Extract social media links and description from AI response
let socialLinks = {};
let description = '';
let quickFacts = {};
let faqs = [];
let jsonFound = false;

// Function to validate social media URLs
function isValidSocialUrl(url, platform) {
  if (!url || typeof url !== 'string') return false;

  // Basic URL validation (no URL global in the sandbox - use a regex)
  if (!/^https?:\/\/[^\s"']+$/.test(url)) {
    return false;
  }

  // Platform-specific validation patterns
  const patterns = {
    twitter: /^https:\/\/(twitter\.com|x\.com)\//,
    linkedin: /^https:\/\/(www\.)?linkedin\.com\/(in|company)\//,
    facebook: /^https:\/\/(www\.)?facebook\.com\//,
    instagram: /^https:\/\/(www\.)?instagram\.com\//,
    youtube: /^https:\/\/(www\.)?youtube\.com\//,
    telegram: /^https:\/\/t\.me\//,
    discord: /^https:\/\/discord\.(com|gg)\//,
    reddit: /^https:\/\/(www\.)?reddit\.com\//,
    tiktok: /^https:\/\/(www\.)?tiktok\.com\//,
    apple: /^https:\/\/apps\.apple\.com\//,
    android: /^https:\/\/play\.google\.com\//,
    wikipedia: /^https:\/\/(en\.)?wikipedia\.org\//,
    github: /^https:\/\/github\.com\//,
    medium: /^https:\/\/(medium\.com|.*\.medium\.com)\//
  };

  return patterns[platform] ? patterns[platform].test(url) : true;
}

// Function to filter out generic/guessed URLs
function filterGenericUrls(socialObj) {
  const filtered = {};

  for (const [platform, url] of Object.entries(socialObj)) {
    if (platform === 'website') {
      filtered[platform] = url; // Always keep website
      continue;
    }

    // Skip if URL looks generic/guessed
    const genericPatterns = [
      new RegExp(`https://${platform}\.com/${meta.name.toLowerCase()}`),
      new RegExp(`https://${platform}\.com/company/${meta.name.toLowerCase()}`),
      new RegExp(`https://${platform}\.com/@${meta.name.toLowerCase()}`)
    ];

    const isGeneric = genericPatterns.some(pattern => pattern.test(url));

    if (!isGeneric && isValidSocialUrl(url, platform)) {
      filtered[platform] = url;
    } else {
      console.log(`Filtered out generic/invalid ${platform} URL: ${url}`);
    }
  }

  return filtered;
}

// Return balanced {...} blocks that mention "social", longest first.
function extractJsonBlocks(text) {
  const out = [];
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '{') continue;
    let depth = 0, inStr = false, esc = false;
    for (let j = i; j < text.length; j++) {
      const c = text[j];
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (c === '{') depth++;
      else if (c === '}') {
        depth--;
        if (depth === 0) {
          const block = text.slice(i, j + 1);
          if (block.indexOf('"social"') !== -1) out.push(block);
          i = j;
          break;
        }
      }
    }
  }
  return out.sort((a, b) => b.length - a.length);
}

try {
  const aiContent = ai.choices?.[0]?.message?.content || ai.content || '';
  console.log('AI Response length:', aiContent.length);

  // Look for JSON object in the response (brace-balanced: the old non-greedy
  // regex truncated at the first '}' and could not survive nested quickFacts/faqs)
  const jsonMatch = extractJsonBlocks(aiContent);
  if (jsonMatch && jsonMatch.length > 0) {
    console.log('Found JSON match:', jsonMatch[0].substring(0, 200));

    // Clean up the JSON string before parsing
    let jsonString = jsonMatch[0];

    // Fix common JSON issues
    jsonString = jsonString
      .replace(/,(s*[}\]])/g, '$1') // Remove trailing commas
      .replace(/([^,{}\s])(s*[}\]])/g, '$1$2') // Ensure proper comma placement
      .replace(/([^,{}\s])(s*"[a-zA-Z_][a-zA-Z0-9_]*"s*:)/g, '$1,$2'); // Add missing commas before properties

    try {
      const aiData = JSON.parse(jsonString);

      // Extract social links
      if (aiData.social) {
        socialLinks = { ...socialLinks, ...aiData.social };
        console.log('Extracted social links:', Object.keys(aiData.social));

        // Filter out generic/guessed URLs
        socialLinks = filterGenericUrls(socialLinks);
        console.log('Filtered social links:', Object.keys(socialLinks));

        jsonFound = true;
      }

      // Extract description
      if (aiData.description) {
        description = aiData.description;
        console.log('Extracted description:', description);
      }

      // Extract quickFacts + faqs (both render in layouts/CryptoOgSingle.js,
      // and faqs feeds the faqSchema() JSON-LD rich result)
      if (aiData.quickFacts && typeof aiData.quickFacts === 'object') {
        quickFacts = aiData.quickFacts;
        console.log('Extracted quickFacts:', Object.keys(quickFacts));
      }
      if (Array.isArray(aiData.faqs)) {
        faqs = aiData.faqs.filter(f => f && f.question && f.answer);
        console.log('Extracted faqs:', faqs.length);
      }
    } catch (jsonError) {
      console.log('JSON parsing failed, trying manual extraction:', jsonError.message);

      // Manual extraction as fallback - search in the full content
      const socialMatch = aiContent.match(/"social"\s*:\s*\{([^}]+)\}/);
      const descMatch = aiContent.match(/"description"\s*:\s*"([^"]+)"/);

      if (socialMatch) {
        // Extract individual social links manually
        const socialText = socialMatch[1];
        const linkMatches = socialText.matchAll(/"([^"]+)"\s*:\s*"([^"]+)"/g);

        for (const match of linkMatches) {
          socialLinks[match[1]] = match[2];
        }

        // Filter out generic/guessed URLs
        socialLinks = filterGenericUrls(socialLinks);

        jsonFound = true;
        console.log('Manual extraction successful:', Object.keys(socialLinks));
      }

      if (descMatch) {
        description = descMatch[1];
        console.log('Manual description extraction:', description);
      }
    }
  }

  // Validate we got the required data
  if (!jsonFound) {
    throw new Error('AI did not return required JSON with social links. Manual review needed.');
  }

  if (!description) {
    throw new Error('AI did not return required description. Manual review needed.');
  }

  // Check if we have minimum required social links
  const socialCount = Object.keys(socialLinks).length;
  if (socialCount < 3) {
    console.log(`Warning: Only ${socialCount} social links found. Consider manual review.`);
  }

} catch (e) {
  console.log('ERROR parsing AI response:', e.message);
  throw new Error(`Failed to extract data from AI response: ${e.message}. Please check AI output format.`);
}

// Build social media section for frontmatter
const socialSection = Object.entries(socialLinks)
  .filter(([key, value]) => value && value.trim())
  .map(([key, value]) => `  ${key}: ${value}`)
  .join('\n');

// YAML-safe double-quoted scalar
const yq = (v) => '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"').trim() + '"';

const quickFactsSection = Object.entries(quickFacts)
  .filter(([k, v]) => v && String(v).trim())
  .map(([k, v]) => `  ${k}: ${yq(v)}`)
  .join('\n');

const faqsSection = faqs
  .map(f => `  - question: ${yq(f.question)}\n    answer: ${yq(f.answer)}`)
  .join('\n');

const frontmatter = ['---',
  `title: ${yq(title)}`,
  `image: "/images/crypto-ogs/${slug}.jpg"`,
  `description: ${yq(description)}`,
  `date: ${isoDate}`,
  `order: ${order}`,
  `authors: ["Oktay Shakirov"]`
];
if (quickFactsSection) frontmatter.push('quickFacts:', quickFactsSection);
if (faqsSection) frontmatter.push('faqs:', faqsSection);
frontmatter.push('social:', socialSection, '---');
const frontmatterText = frontmatter.join('\n');

// Extract just the markdown body (remove any JSON at the end)
let body = ai.choices?.[0]?.message?.content || ai.content || '';
// Remove JSON object if it exists at the end
body = body.replace(/\s*```(?:json)?\s*\{[\s\S]*\}\s*```\s*$/i, '');
body = body.replace(/\s*\{[\s\S]*"(?:description|tags|social)"[\s\S]*\}\s*$/i, '').trim();

// --- hardening (ported from tinnitus pipeline) ---
// no em/en dashes, no double hyphens
body = body.replace(/\u2014/g, ' - ').replace(/[\u2013\u2011]/g, '-').replace(/(^|[^-])--(?!-)/g, '$1-').replace(/  +/g, ' ');
description = description.replace(/\u2014/g, ' - ').replace(/[\u2013\u2011]/g, '-').replace(/  +/g, ' ');
// normalize malformed internal link paths (e.g. /exchanges//exchanges/bitfinex)
body = body.replace(/\]\((\/[^)]*)\)/g, (mm, url) => {
  let u = url.replace(/\/{2,}/g, '/');
  u = u.replace(/^\/(posts|exchanges|crypto-ogs|images)\/(?:\1\/)+/, '/$1/');
  return '](' + u + ')';
});
// straight quotes only (body + description)
const deCurly = (s) => s.replace(/[\u2018\u2019\u201A\u201B]/g, "'").replace(/[\u201C\u201D\u201E\u201F]/g, '"');
body = deCurly(body);
description = deCurly(description);
// dedupe internal links: keep first, unlink repeats
const seenLinks = new Set();
body = body.replace(/(\*\*)?\[([^\]]+)\]\((\/[^)]+)\)(\*\*)?/g, (mm, b1, text, url, b2) => {
  if (url.startsWith('/images/')) return mm; // markdown images share syntax minus '!', keep them
  if (seenLinks.has(url)) return (b1 || '') + text + (b2 || '');
  seenLinks.add(url);
  return mm;
});
// ads never adjacent to images (markdown images here): relocate before final section
let movedAds = 0;
body = body.replace(/(!\[[^\]]*\]\([^)]+\))\s*\n+\s*<ArticleAd \/>/g, (mm, img) => { movedAds++; return img; });
body = body.replace(/<ArticleAd \/>\s*\n+\s*(!\[[^\]]*\]\([^)]+\))/g, (mm, img) => { movedAds++; return img; });
if (movedAds > 0) {
  const lastH = body.lastIndexOf('\n## ');
  if (lastH > -1) body = body.slice(0, lastH) + '\n<ArticleAd />\n' + body.slice(lastH);
}
// Remove OGProfileLinks section if it exists
body = body.replace(/\n## OGProfileLinks[\s\S]*$/, '').trim();

return [{
  json: {
    mdx: `${frontmatterText}\n\n${body}`,
    slug,
    name: meta.name,
    title,

    isoDate,
    order,
    db: meta.db,
    socialLinks
  }
}];

const data = $json;
const filePath = `${data.slug}.mdx`;
const commitMessage = `New Crypto OG: ${data.name}`;

return [{
  json: {
    ...data,
    filePath,
    commitMessage
  }
}];

// Validate file write was successful
const fileResult = $input.first().json;
if (!fileResult || fileResult.error) {
  throw new Error(`File write failed: ${fileResult?.error || 'Unknown error'}`);
}

// Get OG data from Build Frontmatter + MDX node
const ogData = $node["Build Frontmatter + MDX"].json;
if (!ogData || !ogData.name || !ogData.slug) {
  throw new Error('OG data not found or incomplete');
}

// Get and validate database data
const dbData = ogData.db;
if (!dbData) {
  throw new Error('Database data not found');
}

// Create updated database with proper structure
const updatedDb = {
  ...dbData,
  crypto_ogs: { ...(dbData.crypto_ogs || {}) },
  next_orders: { ...(dbData.next_orders || { crypto_ogs: 1 }) }
};

// Create OG key (lowercase, replace spaces with dots)
const ogKey = ogData.name.toLowerCase().replace(/\s+/g, '.');

// Check if OG already exists
if (updatedDb.crypto_ogs[ogKey]) {
  throw new Error(`OG '${ogData.name}' already exists in database`);
}

// Add new OG to database (slug without /crypto-ogs/ prefix)
updatedDb.crypto_ogs[ogKey] = {
  slug: ogData.slug,
  title: ogData.name
};

// Increment next order counter
updatedDb.next_orders.crypto_ogs = (updatedDb.next_orders.crypto_ogs || 0) + 1;

// Return success with updated database
return [{ 
  json: { 
    db: updatedDb, 
    fileSuccess: true, 
    dbSuccess: true,
    ogAdded: ogKey,
    name: ogData.name
  } 
}];
